import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import crypto from 'node:crypto';import {createRequire} from 'node:module';import {execFileSync} from 'node:child_process';
const[base,out]=process.argv.slice(2);if(!base||!out)throw Error('usage: node capture-context.mjs BASE NEW_OUTPUT');fs.mkdirSync(out,{recursive:false});const ts=createRequire(path.join(base,'package.json'))('typescript');const rel='src/sop/staffdeck/SopAgentLoop.ts';const source=fs.readFileSync(path.join(base,rel),'utf8');const ast=ts.createSourceFile(rel,source,ts.ScriptTarget.Latest,true);const names=['renderSopInstruction','text','joinPrompt','sopStepKey'];const functions=names.map(name=>ast.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text===name).getText(ast));const klass=ast.statements.find(n=>ts.isClassDeclaration(n)&&n.name?.text==='SopAgentLoop');const method=klass.members.find(n=>n.name?.getText(ast)==='prepareContext').getText(ast);const code=functions.join('\n')+'\nclass ContextProbe{'+method+'}\nglobalThis.probe=async(row)=>{const p=new ContextProbe();p.preflightSteps=new Map([["parent",{step:row.step}]]);p.protocolCorrections=new Map(row.correction?[["parent",sopStepKey(row.step.skillId,row.step.nodeId)]]:[]);p.stateStore={modelContext:async()=>row.owner};const capability={contextPreparation:{prepareForModel:async input=>input}};return (await p.prepareContext(capability,{sessionId:"parent",appendSystemPrompt:row.existing})).appendSystemPrompt;};';const ctx=vm.createContext({});vm.runInContext(ts.transpileModule(code,{compilerOptions:{target:ts.ScriptTarget.ES2022}}).outputText,ctx,{timeout:1000});const step={skillName:'own procedure',skillId:'procedure',nodeId:'n1',instruction:'Do the node.',expectedUserInfo:[],knownSlots:{},requiredToolNames:[],allowedNextStepIds:[],allowedActions:[],declaresHandoff:false,isTerminal:false};const inputs=[{name:'ordinary-prefix',step,existing:'  SDK prefix  ',correction:false},{name:'blank-prefix',step,existing:' \n ',correction:false},{name:'correction',step,existing:'parent',correction:true},{name:'final-correction',step:{...step,isTerminal:true},existing:'',correction:true},{name:'handoff-correction',step:{...step,isTerminal:true,declaresHandoff:true},correction:true},{name:'utf16-prefix',step:{...step,instruction:'i\ud800'},existing:'s\udc00',correction:true}];const cases=[];for(const row of inputs)cases.push({...row,expected:await ctx.probe(row)});const result={baseline:execFileSync('git',['-C',base,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),node:process.version,icu:process.versions.icu,source:{path:rel,sha256:crypto.createHash('sha256').update(source).digest('hex')},extraction:'Actual prepareContext class method plus actual AST helpers; preflight/state/model context/capability are isolated fake ports; VM has no imports or network',cases};const bytes=JSON.stringify(result,null,2)+'\n';fs.writeFileSync(path.join(out,'context-oracle.json'),bytes);console.log(JSON.stringify({cases:cases.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex')}));
